from pathlib import Path
import json,hashlib,struct
R=Path(__file__).resolve().parent
items=[('basic_rod','木柄鱼竿','wooden rod, teal reel and cream line'),('bait','通用鱼饵','wooden bait cup with coral worm curls'),('sardine','银纹沙丁鱼','slender silver sardine, dark plain back'),('mackerel','青背鲭鱼','teal mackerel with dark stripes'),('sea_bass','花斑海鲈','broad spotted olive bass with spiny dorsal fin')]
def desc(p):
 b=p.read_bytes();return {'path':str(p.relative_to(R)),'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'size':list(struct.unpack('>II',b[16:24]))}
manifest={'id':'m3-life-b-assets-v1','version':'1.0.0','catalogRevision':1,'designOnly':True,'itemAssetIdPattern':'life-item-<itemId>','export':{'format':'RGBA PNG','logicalSize':[32,32],'transparentMarginMin':3,'displaySizes':[32,64,96,128],'sampling':'nearest','sourceTool':'built-in image_gen','promptDirectory':'prompts/','technicalExport':'image-export.json'},'items':[],'atlas':desc(R/'assets/items/items-atlas.png'),'nativeSources':'native-sources.json','animationManifest':'animation-manifest.json','productionDestination':{'items':'apps/web/public/world-life/b/items/','fishing':'apps/web/public/world-life/b/fishing/','runtimeUrlPrefix':'/assets/world-life/b/','generatedMasters':'design repository only; do not serve full-resolution masters on inventory open'}}
for i,(id,name,alt)in enumerate(items):manifest['items'].append({'assetId':'life-item-'+id,'itemId':id,'name':name,'alt':alt,'sprite':desc(R/f'assets/items/{id}.png'),'frame':[i*32,0,32,32],'pivot':[16,16],'master':desc(R/f'assets/generated/{id}.png'),'prompt':f'prompts/{id}.txt','source':'Generated with built-in image_gen for this project; not copied from another game','availability':'actual image delivered'})
(R/'assets-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n')
clips=[]
for id,a,n,frames,ms,loop in [('fishing-cast','casting',15,list(range(15)),80,False),('fishing-wait','waiting',9,[0,2,4,6],300,True),('fishing-reel','reeling',13,list(range(13)),80,False),('fishing-caught','caught',10,list(range(10)),80,False)]:
 layers={k:desc(R/f'assets/fishing/{k}_{a}_strip{n}.png') for k in ['base','tools','shorthair','longhair','curlyhair','bowlhair','mophair','spikeyhair']}
 clips.append({'assetId':id,'action':a,'sourceFrameCount':n,'frameSize':[96,64],'feet':[48,39],'frames':frames,'frameDurationMs':ms,'loop':loop,'facingNative':'right','left':'mirror whole base/hair/tools about feet pivot; never mirror one layer alone','layerOrder':['base','selected hair','tools'],'layers':layers,'reducedMotionFrame':frames[-1] if a=='caught' else frames[0]})
(R/'animation-manifest.json').write_text(json.dumps({'id':'m3-life-b-fishing-animations-v1','nativeSource':'Sunnyside_World_ASSET_PACK_V2.1','bodySize':[96,64],'feet':[48,39],'clips':clips,'npc':{'npcId':'npc-fishing-clerk','lookId':'sunnyside-human-spikeyhair','catalogVersion':'2026-10-21.appearance-v1.1','idle':{'base':'assets/fishing/base_idle_strip9.png','hair':'assets/fishing/spikeyhair_idle_strip9.png','frames':9,'frameDurationMs':125},'walk':{'base':'assets/fishing/base_walk_strip8.png','hair':'assets/fishing/spikeyhair_walk_strip8.png','frames':8,'frameDurationMs':100}},'authority':'Animations never produce receipts, money, fish, reservations or station occupancy. Completion and fish icon require actual result; deduplicate terminal receipt.'},ensure_ascii=False,indent=2)+'\n')
print({'itemCount':len(items),'atlas':manifest['atlas'],'nativeLayers':sum(len(c['layers']) for c in clips),'source':'actual raster PNG files'})
